#include "ml_structures.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
enum { ROWS=50000,FEATURES=16,BATCH=128,EMB_ROWS=20000,DIMS=32,GATHER=10000 };
int main(void){MlDataset*d=ml_dataset_create(ROWS,FEATURES);assert(d&&ml_dataset_validate(d));float row[FEATURES];for(size_t r=0;r<ROWS;++r){for(size_t f=0;f<FEATURES;++f)row[f]=(float)(r*32U+f);assert(ml_dataset_set_row(d,r,row,(int)(r%10U)));}BatchPlan*p=batch_plan_create(ROWS,BATCH,UINT64_C(1234567));assert(p&&batch_plan_validate(p));unsigned char*seen=calloc(ROWS,1U);float*bx=malloc((size_t)BATCH*FEATURES*sizeof(*bx));int*by=malloc((size_t)BATCH*sizeof(*by));assert(seen&&bx&&by);size_t total=0U;for(;;){const size_t*idx=NULL;size_t count=0U;bool has=false;assert(batch_plan_next(p,&idx,&count,&has));if(!has)break;assert(ml_dataset_gather(d,idx,count,bx,by));for(size_t i=0;i<count;++i){size_t src=idx[i];assert(!seen[src]);seen[src]=1U;assert(by[i]==(int)(src%10U));for(size_t f=0;f<FEATURES;++f)assert(bx[i*FEATURES+f]==(float)(src*32U+f));}total+=count;}assert(total==ROWS);for(size_t i=0;i<ROWS;++i)assert(seen[i]);assert(batch_plan_reset(p,UINT64_C(7654321),true)&&batch_plan_validate(p));EmbeddingTable*e=embedding_create(EMB_ROWS,DIMS);assert(e&&embedding_validate(e));float erow[DIMS];for(size_t r=0;r<EMB_ROWS;++r){for(size_t j=0;j<DIMS;++j)erow[j]=(float)(r*64U+j);assert(embedding_set_row(e,r,erow));}size_t*idx=malloc((size_t)GATHER*sizeof(*idx));float*out=malloc((size_t)GATHER*DIMS*sizeof(*out));assert(idx&&out);for(size_t i=0;i<GATHER;++i)idx[i]=(i*37U)%EMB_ROWS;assert(embedding_gather(e,idx,GATHER,out));for(size_t i=0;i<GATHER;++i)for(size_t j=0;j<DIMS;++j)assert(out[i*DIMS+j]==(float)(idx[i]*64U+j));printf("AI/ML structures tests passed; rows=%zu batch=%zu embeddings=%zu x %zu\n",ml_dataset_rows(d),batch_plan_batch_size(p),embedding_rows(e),embedding_dims(e));free(out);free(idx);embedding_free(e);free(by);free(bx);free(seen);batch_plan_free(p);ml_dataset_free(d);return 0;}
